insert into categories (name, slug, description, image_url, sort_order, is_active, overview, key_points, applications, buying_guide, faqs) values ('Compaction & Earthmoving', 'compaction-earthmoving', 'Double Drum Roller, Earth Compactor, Plate Compactor, Reversible Earth Compactor, Ride On Road Roller, Scarifier Machine', '/catalog/categories/1790578586808_PLATE_COMPACTOR_2.webp', 1, true, 'Compaction and earthmoving equipment prepares the ground for everything built on it. Walk-behind and ride-on rollers, plate compactors, earth compactors and tamping rammers remove air voids from soil, aggregate and asphalt so roads, slabs and foundations carry load without settling.
insert into categories (name, slug, description, image_url, sort_order, is_active, overview, key_points, applications, buying_guide, faqs) values ('Concrete Consolidation', 'concrete-consolidation', 'Concrete Consolidation - Internal Vibrator, Concrete Pump, Concrete Vibrator, Electrical Vibrator, Handy Vibrator, Hawk Needle', '/catalog/categories/1790579270180_HIGH_FREQUENCY_CONVERTERS___POKERS.webp', 2, true, 'Concrete consolidation equipment removes entrapped air from freshly placed concrete so it reaches its designed strength and a dense, honeycomb-free finish. Needle (poker) vibrators, high-frequency converters and surface vibrators are used on columns, beams, slabs and precast work.', array['Needle / poker vibrators','High-frequency converters and pokers','Flexible shafts and needles in multiple sizes','Electric and engine-driven drives','Genuine spares and accessories']::text[], array['Columns, beams and walls','Slabs and rafts','Precast and bridge works','Ready-mix and infrastructure projects']::text[], '[{"title": "Needle diameter", "text": "Choose needle size to suit the section and rebar spacing \u2014 smaller needles for congested reinforcement."}, {"title": "Drive type", "text": "Electric drives suit sites with power; engine drives suit remote locations."}, {"title": "High frequency", "text": "High-frequency pokers give faster, more uniform consolidation on large pours."}]'::jsonb, '[{"q": "How long should I vibrate?", "a": "Typically 5\u201315 seconds per insertion, until air bubbles stop rising and the surface glistens."}, {"q": "Do you supply spare needles and shafts?", "a": "Yes, shafts, needles and spares are available for the equipment we supply."}]'::jsonb) on conflict (slug) do update set name = excluded.name, description = excluded.description, image_url = excluded.image_url, sort_order = excluded.sort_order, is_active = true, overview = excluded.overview, key_points = excluded.key_points, applications = excluded.applications, buying_guide = excluded.buying_guide, faqs = excluded.faqs;
insert into categories (name, slug, description, image_url, sort_order, is_active, overview, key_points, applications, buying_guide, faqs) values ('Concrete Finishing', 'concrete-finishing', 'Bull Float, Bump Cutter, Cement Sanding Machine, Concrete Cutter, Double Beam Screed Board Vibrator, Edger', '/catalog/categories/1790578628898_GROOVE_CUTTER_-_ROAD_CUTTING_MACHINE2.webp', 3, true, 'Concrete finishing equipment produces flat, durable and accurately cut concrete surfaces. Power trowels float and polish slabs, screeds level fresh concrete, and groove cutters and road cutting machines cut joints and channels in concrete and asphalt.', array['Power trowels and floaters','Screeds and levelling equipment','Groove cutters and road cutting machines','Floor and joint cutting solutions','Blades, pans and accessories']::text[], array['Industrial and warehouse floors','Roads and pavements','Expansion and control joints','Commercial and residential slabs']::text[], '[{"title": "Trowel size", "text": "Larger trowels give more output on big slabs; smaller trowels suit rooms and edges."}, {"title": "Cutting depth", "text": "Blade diameter decides maximum cutting depth \u2014 match it to the joint depth required."}, {"title": "Power source", "text": "Petrol units are portable; electric units suit indoor and enclosed work."}]'::jsonb, '[{"q": "When should joints be cut?", "a": "Usually within 6\u201318 hours of placing, once the concrete can be cut without ravelling."}, {"q": "Do you supply blades?", "a": "Yes, finishing blades, float pans and cutting blades are available."}]'::jsonb) on conflict (slug) do update set name = excluded.name, description = excluded.description, image_url = excluded.image_url, sort_order = excluded.sort_order, is_active = true, overview = excluded.overview, key_points = excluded.key_points, applications = excluded.applications, buying_guide = excluded.buying_guide, faqs = excluded.faqs;
insert into categories (name, slug, description, image_url, sort_order, is_active, overview, key_points, applications, buying_guide, faqs) values ('Construction Access Solution', 'construction-access-solution', 'Suspended Platforms', '/catalog/categories/1790579542137_ZLP800.webp', 4, true, 'Construction access solutions provide safe working platforms at height. Suspended platforms (gondolas) are used for façade work, glazing, painting and maintenance on multi-storey buildings.', array['Suspended working platforms','Hoist motors with safety locks','Modular platform lengths','Installation support']::text[], array['Façade and glazing works','External painting and plastering','Building maintenance']::text[], '[{"title": "Platform length", "text": "Choose platform length to suit the fa\u00e7ade bay width and crew size."}, {"title": "Rated load", "text": "Allow for workers, tools and materials within the rated load."}]'::jsonb, '[{"q": "Do you help with installation?", "a": "Yes \u2014 our team supports installation and operator briefing."}]'::jsonb) on conflict (slug) do update set name = excluded.name, description = excluded.description, image_url = excluded.image_url, sort_order = excluded.sort_order, is_active = true, overview = excluded.overview, key_points = excluded.key_points, applications = excluded.applications, buying_guide = excluded.buying_guide, faqs = excluded.faqs;
insert into categories (name, slug, description, image_url, sort_order, is_active, overview, key_points, applications, buying_guide, faqs) values ('Material Testing & Civil Laboratory System', 'material-testing', 'Compression Testing Machine, Compression Testing Machine Electrical', '/catalog/categories/1790579499514_CMT100.webp', 5, true, 'Material testing and civil laboratory systems verify the quality of concrete, cement, soil and aggregates on site and in the lab. Compression testing machines and related equipment help projects meet IS standards and quality-control requirements.', array['Compression testing machines','Manual and electrical operation','Equipment conforming to IS standards','Calibration support']::text[], array['Site quality-control labs','Ready-mix concrete plants','Precast yards','Educational and testing institutes']::text[], '[{"title": "Capacity", "text": "Select load capacity to suit cube and cylinder sizes you test."}, {"title": "Operation", "text": "Electrical units speed up testing; hand-operated units suit low volumes."}]'::jsonb, '[{"q": "Are machines calibrated?", "a": "Machines are supplied with works calibration; third-party calibration can be arranged."}]'::jsonb) on conflict (slug) do update set name = excluded.name, description = excluded.description, image_url = excluded.image_url, sort_order = excluded.sort_order, is_active = true, overview = excluded.overview, key_points = excluded.key_points, applications = excluded.applications, buying_guide = excluded.buying_guide, faqs = excluded.faqs;
insert into categories (name, slug, description, image_url, sort_order, is_active, overview, key_points, applications, buying_guide, faqs) values ('Mobile Concrete Mixing', 'mobile-concrete-mixing', 'Concrete Mixer, Concrete Mixer Barrow Type, Concrete Mixer Classic Type', '/catalog/categories/1790578833847_SMT250E.webp', 6, true, 'Mobile concrete mixing equipment produces consistent concrete right where it is needed. Drum mixers and self-loading mixers reduce manual handling and give better quality control than hand mixing on small and medium projects.', array['Drum concrete mixers','Electric and diesel options','Towable and wheeled designs','Robust drums and frames']::text[], array['Residential and commercial construction','Rural and road works','Small infrastructure projects']::text[], '[{"title": "Drum capacity", "text": "Choose capacity to match batch size and daily output."}, {"title": "Power", "text": "Electric mixers suit sites with power; diesel mixers suit remote sites."}]'::jsonb, '[{"q": "What output can I expect?", "a": "Output depends on drum capacity and cycle time \u2014 ask our team for a site estimate."}]'::jsonb) on conflict (slug) do update set name = excluded.name, description = excluded.description, image_url = excluded.image_url, sort_order = excluded.sort_order, is_active = true, overview = excluded.overview, key_points = excluded.key_points, applications = excluded.applications, buying_guide = excluded.buying_guide, faqs = excluded.faqs;
insert into categories (name, slug, description, image_url, sort_order, is_active, overview, key_points, applications, buying_guide, faqs) values ('Optical Instruments', 'optical-instruments', 'Advanced features for maximum measurement versatility and unmatched product and data security. The FX total station provides the advantage of on-board Windows® Embedded Compact 7 operating system and comes standard with MAGNET™ Sokkia Field, the cloud-based application software for unmatched measurement ease and data security., Built for job site mobility, the flagship iX Series robotic total station enables accurate and productive workflows for highly demanding survey and construction applications. Precisely lay out or survey more points in less time and improve quality and consistency. Easy-to-use digital processes with repeatably accurate results mean less rework and better quality control. iX is one professional tool that does it all for survey and layout., Sokkia Measuring Station Opens New Era in Ultra-Precision 3D Measurement. Featuring a wide array of innovative technologies, the NET AXII 0.5" and NET AXII 1" total stations offer superior performance in angle and distance measurement as well as reliable robotic functionality. The NET ensures dramatic enhancement in precision and productivity in all applications such as surveying, engineering, construction, monitoring and 3D industrial measurement., The DT50 is a lightweight, compact alignment and angular measurement device which boasts up to 30 workdays of power; the highest water and dust protection in its category; and convenient, high-precision laser guidance., The iM-100 (Intelligent Measurement Total Station) incorporates all the features you need at a cost-efficient price. It will handle your most demanding survey layout or as-built project needs. You get fast, accurate, and powerful EDM technology, best-in-class accuracy up to 5,000 m with a prism and up to 800 m in reflectorless mode, and a battery life of up to 28 hours. The iM-100 is ready to be your hardest worker out in the field., The iM-50 Series is the perfect entry-level site layout and survey tool offering reliability and flexibility without sacrificing cost or functionality. The sleek design is built tough, with a water and dustproof IP66 rating, integrated Bluetooth® capability and an internal antenna, enabling you to deliver measurements cable-free to your data controller, streamlining your equipment weight and workflow. The iM-50 is also armed with a top line EDM, generous internal memory storage, and SDRbasic on-board software so you have everything you need to get the job done out in the field.', '/catalog/categories/1789724423752_product-gallert-im-60-series01.webp', 7, true, 'Optical survey instruments from Sokkia deliver accurate measurement for setting out, levelling and surveying. Total stations, auto levels and related instruments support construction, infrastructure and land survey work.', array['Total stations','Auto levels','Accessories and tripods','Service and calibration support']::text[], array['Construction setting out','Road and infrastructure survey','Land and topographic survey']::text[], '[{"title": "Accuracy", "text": "Choose angular accuracy to suit your survey tolerance."}, {"title": "Range", "text": "Consider prism and reflectorless range for your typical distances."}]'::jsonb, '[{"q": "Do you calibrate instruments?", "a": "Calibration and service support can be arranged for the instruments we supply."}]'::jsonb) on conflict (slug) do update set name = excluded.name, description = excluded.description, image_url = excluded.image_url, sort_order = excluded.sort_order, is_active = true, overview = excluded.overview, key_points = excluded.key_points, applications = excluded.applications, buying_guide = excluded.buying_guide, faqs = excluded.faqs;
insert into categories (name, slug, description, image_url, sort_order, is_active, overview, key_points, applications, buying_guide, faqs) values ('Mobile Lighting Solutions', 'portable-light-tower', 'Whether you’re working on a construction site, conducting emergency repairs, or organizing a nighttime event, darkness shouldn’t slow you down. Our Light Tower is designed to provide bright, reliable illumination, ensuring safety, efficiency, and productivity in any environment.', '/catalog/categories/1790578268082_HALO1.webp', 8, true, 'Mobile lighting solutions provide bright, safe illumination for night work, road works, mining and events. Portable LED light towers deliver wide-area lighting with low fuel consumption.', array['Portable LED light towers','Telescopic masts','Low fuel consumption','Easy site movement']::text[], array['Night-time construction','Road works','Mining and quarry sites','Events and emergency response']::text[], '[{"title": "Coverage", "text": "Mast height and lamp output decide the area lit."}, {"title": "Run time", "text": "Larger fuel tanks give longer unattended run time."}]'::jsonb, '[{"q": "How long can a light tower run?", "a": "Run time depends on model and tank size \u2014 many LED towers run through multiple nights per tank."}]'::jsonb) on conflict (slug) do update set name = excluded.name, description = excluded.description, image_url = excluded.image_url, sort_order = excluded.sort_order, is_active = true, overview = excluded.overview, key_points = excluded.key_points, applications = excluded.applications, buying_guide = excluded.buying_guide, faqs = excluded.faqs;
insert into categories (name, slug, description, image_url, sort_order, is_active, overview, key_points, applications, buying_guide, faqs) values ('Rebar Processing', 'rebar-processing', 'Bar Bending Machine, CNC Stirrup Binder, CNC Wire Straightening, Portable Bar Bending, Portable Bar Cutting, Portable Bar Threading', '/catalog/categories/1790579057451_REBAR_CUTTING_MACHINE.webp', 9, true, 'Rebar processing equipment cuts, bends and shapes reinforcement steel accurately on site. Rebar bending machines, cutting machines and related equipment speed up reinforcement work and reduce wastage compared with manual methods.', array['Rebar bending machines','Rebar cutting machines','Capacities for TMT bars up to 32–50 mm','Automatic modes and planetary gearboxes','Service and spares support']::text[], array['Building construction','Bridges and flyovers','Precast yards','Infrastructure projects']::text[], '[{"title": "Bar diameter", "text": "Choose machine capacity for the largest TMT bar grade and diameter you process."}, {"title": "Motor and speed", "text": "Higher motor power and rotation speed increase daily output."}, {"title": "Mode", "text": "Automatic machines improve repeatability on large jobs."}]'::jsonb, '[{"q": "Which bar grades can be processed?", "a": "Each machine lists its rated TMT grade and maximum diameter in the specifications."}]'::jsonb) on conflict (slug) do update set name = excluded.name, description = excluded.description, image_url = excluded.image_url, sort_order = excluded.sort_order, is_active = true, overview = excluded.overview, key_points = excluded.key_points, applications = excluded.applications, buying_guide = excluded.buying_guide, faqs = excluded.faqs;
insert into categories (name, slug, description, image_url, sort_order, is_active, overview, key_points, applications, buying_guide, faqs) values ('Steel Processing', 'steel-processing', 'Portable Angle Cutter, Portable Punching Machine, Punching and Shearing Machine', '/catalog/categories/1790579631218_QA3512.webp', 10, true, 'Steel processing equipment handles cutting and shaping of steel sections and plates for fabrication and construction, improving speed and accuracy on site and in workshops.', array['Steel cutting and shaping machines','Robust industrial construction','Service and spares support']::text[], array['Fabrication workshops','Structural steel works','Construction sites']::text[], '[{"title": "Capacity", "text": "Match machine capacity to the section sizes you process."}]'::jsonb, '[{"q": "Do you provide demonstrations?", "a": "Contact our team to arrange a demonstration."}]'::jsonb) on conflict (slug) do update set name = excluded.name, description = excluded.description, image_url = excluded.image_url, sort_order = excluded.sort_order, is_active = true, overview = excluded.overview, key_points = excluded.key_points, applications = excluded.applications, buying_guide = excluded.buying_guide, faqs = excluded.faqs;
insert into brands (name, slug, logo_url, is_active, description) values ('C.R.I Pumps', 'c-r-i-pumps', '/catalog/brands/1789717172281_Picsart_26-06-25_14-29-15-055_1.webp', true, 'Commitment Reliability Innovation – C.R.I. ranks high among the world''s fastest-growing fluid management solution providers with a wide global presence. C.R.I. offers Pumps, Motors, Valves, IoT Drives & Controllers, Pipes, Wires & Cables, and Solar Pumping Systems. C.R.I. Group has a diversified range of 9,000+ products in its portfolio and is among the few to manufacture 100 percent stainless steel pumps in the world. The company has 21+ manufacturing facilities across the globe and has made acquisitions in U.K. and Italy. The R&D division - "Fludyn Advanced Technology Centre" is recognized by the Ministry of Science & Technology, Govt of India. India''s top exporter; winner of EEPC (Engineering Export Promotion Council) award 22 times and also won the National Energy Conservation (NEC) award from the Government of India for 8 times. C.R.I. Fluid Systems products cater to diverse segments such as: Chemical & Process, Power, Water & Waste Water, Oil & Gas, Pharma, Sugar & Distilleries, Paper & Pulp, Marine & Defence, Metal & Mining, Food & Beverage, Petrochemical & Refineries, Solar, Building, HVAC, Fire Fighting, Agriculture & Residential.') on conflict (slug) do update set name = excluded.name, logo_url = excluded.logo_url, is_active = true, description = excluded.description;
insert into brands (name, slug, logo_url, is_active, description) values ('Greaves Cotton', 'greaves-cotton', '/catalog/brands/1791389543685_WhatsApp_Image_2026-10-06_at_1.53.32_PM__2_-removebg-preview__1___1_.webp', true, 'Greaves Cotton Limited (GCL), also known as Greaves, is a diversified, multi-product, multi-fuel, and multi-location engineering company with a legacy of 165 years and strong brand trust. Originally renowned for its single-cylinder diesel engines, Greaves has transformed into a fuel-agnostic, end-to-end mobility solutions provider, driven by the purpose of “Empowering Lives”. The Company is enabling a sustainable transition to green mobility and aims to touch a billion lives by 2030. Greaves is building a digitally integrated ecosystem that connects consumers, business partners, and service providers across the entire mobility value chain.') on conflict (slug) do update set name = excluded.name, logo_url = excluded.logo_url, is_active = true, description = excluded.description;
insert into brands (name, slug, logo_url, is_active, description) values ('Lubi', 'lubi', '/catalog/brands/1791388645567_WhatsApp_Image_2026-10-06_at_1.53.32_PM__1_-removebg-preview.webp', true, 'Lubi') on conflict (slug) do update set name = excluded.name, logo_url = excluded.logo_url, is_active = true, description = excluded.description;
insert into brands (name, slug, logo_url, is_active, description) values ('Sokkia', 'sokkia', '/catalog/brands/1789716823500_image_123.webp', true, 'Our diverse product line provides complete measurement solutions for surveying, mapping and GIS, industrial measurement and construction applications. SOKKIA products have been used to complete major projects worldwide; from the “Big Dig” in Boston, Mass., to the New Bangkok International Airport in Thailand. We provide turn-key solutions for surveyors worldwide. Our total stations, GNSS receivers, data collectors, digital levels, and a full complement of field accessories are available through a nationwide distribution network. For more than 100 years, our complete line of surveying instruments, GNSS products and accessories have provided its customers with quality found nowhere else. With our products, you will be sure to have long-lasting, precise instruments for many years to come. Our customers will continue to see this rugged and reliable quality with innovations in the GNSS product line, an expansion of construction-specific instruments and continued enhancements on our high precision robotic total stations.') on conflict (slug) do update set name = excluded.name, logo_url = excluded.logo_url, is_active = true, description = excluded.description;
insert into brands (name, slug, logo_url, is_active, description) values ('STROKE', 'stroke', '/catalog/brands/1791389745056_stroke__1_.webp', true, 'Committed to superior quality & results. Innovative construction solutions and the highest quality of construction equipment make Stroke the preferred choice of industry experts globally. Setting gold standards with our light construction equipment and our powerful range of mini excavators, we are a force to reckon with in the fields of infrastructure and building construction.') on conflict (slug) do update set name = excluded.name, logo_url = excluded.logo_url, is_active = true, description = excluded.description;
insert into brands (name, slug, logo_url, is_active, description) values ('Uniq Engg Co', 'uniq-engg-co', '/catalog/brands/1791388581949_WhatsApp_Image_2026-10-06_at_1.42.26_PM__1_-removebg-preview.webp', true, 'Shakti Traders - Manufacturer of Construction Equipments') on conflict (slug) do update set name = excluded.name, logo_url = excluded.logo_url, is_active = true, description = excluded.description;
insert into products (sku, slug, name, brand_id, manufacturer, category_id, model_number, short_description, description, unit, selling_price, tax_rate, price_visibility, reorder_threshold, is_featured, featured_rank, status, is_sample_data, features, warranty) values ('250L', '250l', '250L CONCRETE MIXER', (select id from brands where slug = 'uniq-engg-co'), 'Uniq Engg Co', (select id from categories where slug = 'mobile-concrete-mixing'), '250L CONCRETE MIXER', 'Concrete Mixer', 'The 250L CONCRETE MIXER is a concrete mixer from Uniq Engg Co, part of our Mobile Concrete Mixing range. Key specifications — Dimension: 1500mm x 760mm x 1100mm; Weight: 145kg; Upper drum thickness: 2mm; Bottom drum thickness: 2.4mm. Contact our team for pricing, availability, demonstrations and after-sales support.', 'Nos', null, 18, 'on_request', 1, true, 1, 'active', false, '{}'::text[], 'As per manufacturer warranty terms.') on conflict (sku) do update set name = excluded.name, brand_id = excluded.brand_id, category_id = excluded.category_id, short_description = excluded.short_description, description = excluded.description, features = excluded.features, is_featured = excluded.is_featured, featured_rank = excluded.featured_rank, status = 'active';
insert into product_specifications (product_id, spec_group, label, value, sort_order) select id, v.g, v.l, v.v, v.o from products, (values ('Overview', 'Type', 'Concrete Mixer', 0), ('Specifications', 'Dimension', '1500mm x 760mm x 1100mm', 1), ('Specifications', 'Weight', '145kg', 2), ('Specifications', 'Upper drum thickness', '2mm', 3), ('Specifications', 'Bottom drum thickness', '2.4mm', 4), ('Specifications', 'Wheel Size', '4.00-8 4 solid rubber wheels', 5)) as v(g, l, v, o) where sku = '250L';
insert into product_images (product_id, url, alt, sort_order) select id, '/catalog/products/1790340771459_250l__2_.webp', '250L CONCRETE MIXER', 0 from products where sku = '250L';
insert into products (sku, slug, name, brand_id, manufacturer, category_id, model_number, short_description, description, unit, selling_price, tax_rate, price_visibility, reorder_threshold, is_featured, featured_rank, status, is_sample_data, features, warranty) values ('BB-43', 'bb-43', 'BB 43', (select id from brands where slug = 'stroke'), 'STROKE', (select id from categories where slug = 'rebar-processing'), 'BB 43', 'Rebar Bending Machine', 'The BB 43 is a rebar bending machine from STROKE, part of our Rebar Processing range. Key specifications — Prime Motor: 3kw Motor (Elec); Dimensions: 800 x 720 x 900mm; Mode of Operation: Automatic; Rotation Speed: 7 r / min. Contact our team for pricing, availability, demonstrations and after-sales support.', 'Nos', null, 18, 'on_request', 1, true, 2, 'active', false, '{}'::text[], 'As per manufacturer warranty terms.') on conflict (sku) do update set name = excluded.name, brand_id = excluded.brand_id, category_id = excluded.category_id, short_description = excluded.short_description, description = excluded.description, features = excluded.features, is_featured = excluded.is_featured, featured_rank = excluded.featured_rank, status = 'active';
insert into product_specifications (product_id, spec_group, label, value, sort_order) select id, v.g, v.l, v.v, v.o from products, (values ('Overview', 'Type', 'Rebar Bending Machine', 0), ('Specifications', 'Prime Motor', '3kw Motor (Elec)', 1), ('Specifications', 'Dimensions', '800 x 720 x 900mm', 2), ('Specifications', 'Mode of Operation', 'Automatic', 3), ('Specifications', 'Rotation Speed', '7 r / min', 4), ('Specifications', 'Grade', 'TMT FE500 (upto 32mm)', 5), ('Specifications', 'Machine Weight', '320 Kgs', 6)) as v(g, l, v, o) where sku = 'BB-43';
insert into product_images (product_id, url, alt, sort_order) select id, '/catalog/products/1790576437263_REBAR_BENDING_MACHINE.webp', 'BB 43', 0 from products where sku = 'BB-43';
insert into products (sku, slug, name, brand_id, manufacturer, category_id, model_number, short_description, description, unit, selling_price, tax_rate, price_visibility, reorder_threshold, is_featured, featured_rank, status, is_sample_data, features, warranty) values ('BB-53', 'bb-53', 'BB 53', (select id from brands where slug = 'stroke'), 'STROKE', (select id from categories where slug = 'rebar-processing'), 'BB 53', 'Rebar Bending Machine', 'The BB 53 is a rebar bending machine from STROKE, part of our Rebar Processing range. Key specifications — Prime Motor: 4kw Motor (Elec); Dimensions: 860 x 760 x 900mm; Mode of Operation: Automatic, Planetary Gearbox; Rotation Speed: 15 r / min. Contact our team for pricing, availability, demonstrations and after-sales support.', 'Nos', null, 18, 'on_request', 1, false, 100, 'active', false, '{}'::text[], 'As per manufacturer warranty terms.') on conflict (sku) do update set name = excluded.name, brand_id = excluded.brand_id, category_id = excluded.category_id, short_description = excluded.short_description, description = excluded.description, features = excluded.features, is_featured = excluded.is_featured, featured_rank = excluded.featured_rank, status = 'active';
