insert into products (sku, slug, name, brand_id, manufacturer, category_id, model_number, short_description, description, unit, selling_price, tax_rate, price_visibility, reorder_threshold, is_featured, featured_rank, status, is_sample_data, features, warranty) values ('BB-53-PRO', 'bb-53-pro', 'BB 53 PRO', (select id from brands where slug = 'stroke'), 'STROKE', (select id from categories where slug = 'rebar-processing'), 'BB 53 PRO', 'Rebar Bending Machine', 'The BB 53 PRO is a rebar bending machine from STROKE, part of our Rebar Processing range. Key specifications — Prime Motor: 5.5Kw Motor (Elec); Dimensions: 950 x 800 x 1073mm; Mode of Operation: Automatic, Planetary Gearbox; Rotation Speed: 13 r / min. Contact our team for pricing, availability, demonstrations and after-sales support.', 'Nos', null, 18, 'on_request', 1, false, 100, 'active', false, '{}'::text[], 'As per manufacturer warranty terms.') on conflict (sku) do update set name = excluded.name, brand_id = excluded.brand_id, category_id = excluded.category_id, short_description = excluded.short_description, description = excluded.description, features = excluded.features, is_featured = excluded.is_featured, featured_rank = excluded.featured_rank, status = 'active';
