ment System','RED-Tech advanced reflectorless measurement','Long-Range Bluetooth® wireless communication','Available in 1, 3, and 5 second models']::text[], 'As per manufacturer warranty terms.') on conflict (sku) do update set name = excluded.name, brand_id = excluded.brand_id, category_id = excluded.category_id, short_description = excluded.short_description, description = excluded.description, features = excluded.features, is_featured = excluded.is_featured, featured_rank = excluded.featured_rank, status = 'active';
