insert into products (sku, slug, name, brand_id, manufacturer, category_id, model_number, short_description, description, unit, selling_price, tax_rate, price_visibility, reorder_threshold, is_featured, featured_rank, status, is_sample_data, features, warranty) values ('IM-100-SERIES', 'im-100-series', 'iM-100 Series', (select id from brands where slug = 'sokkia'), 'Sokkia', (select id from categories where slug = 'optical-instruments'), 'iM-100 Series', 'The iM-100 (Intelligent Measurement Total Station) incorporates all the features you need at a cost-efficient price. It will handle your most demanding survey layout or as-built project needs. You get fast, accurate, and powerful EDM technology, best-in-class accuracy up to 5,000 m with a prism and up to 800 m in reflectorless mode, and a battery life of up to 28 hours. The iM-100 is ready to be your hardest worker out in the field.', 'The iM-100 Series is a the im-100 (intelligent measurement total station) incorporates all the features you need at a cost-efficient price. it will handle your most demanding survey layout or as-built project needs. you get fast, accurate, and powerful edm technology, best-in-class accuracy up to 5,000 m with a prism and up to 800 m in reflectorless mode, and a battery life of up to 28 hours. the im-100 is ready to be your hardest worker out in the field. from Sokkia, part of our Optical Instruments range. Key specifications — Magnification / Resolving power: 30x / 2.5"; Length: 171 mm (6.7 in.); Objective aperture: 45 mm (1.8 in.) (48 mm (1.9 in.) for EDM); Display Resolution: 1" / 5". Contact our team for pricing, availability, demonstrations and after-sales support.', 'Nos', null, 18, 'on_request', 1, false, 100, 'active', false, array['Fast, accurate and powerful EDM','Integrated Blueooth® technology - no external antenna necessary for connectivity with the controller','Dual axis compensation','Waterproof IP66 rating','Up to 28 hours of battery life in Eco mode']::text[], 'As per manufacturer warranty terms.') on conflict (sku) do update set name = excluded.name, brand_id = excluded.brand_id, category_id = excluded.category_id, short_description = excluded.short_description, description = excluded.description, features = excluded.features, is_featured = excluded.is_featured, featured_rank = excluded.featured_rank, status = 'active';
insert into product_specifications (product_id, spec_group, label, value, sort_order) select id, v.g, v.l, v.v, v.o from products, (values ('Overview', 'Type', 'The iM-100 (Intelligent Measurement Total Station) incorporates all the features you need at a cost-efficient price. It will handle your most demanding survey layout or as-built project needs. You get fast, accurate, and powerful EDM technology, best-in-class accuracy up to 5,000 m with a prism and up to 800 m in reflectorless mode, and a battery life of up to 28 hours. The iM-100 is ready to be your hardest worker out in the field.', 0), ('Specifications', 'Magnification / Resolving power', '30x / 2.5"', 1), ('Specifications', 'Length', '171 mm (6.7 in.)', 2), ('Specifications', 'Objective aperture', '45 mm (1.8 in.) (48 mm (1.9 in.) for EDM)', 3), ('Specifications', 'Display Resolution', '1" / 5"', 4), ('Specifications', 'Accuracy (ISO 17123-3:2001)', 'iM-102 = "2", iM-103 = "3", iM = "5"', 5), ('Specifications', 'Internal memory', 'Approx. 50,000 points', 6), ('Specifications', 'Plug-in memory device', 'USB flash memory (max. 32GB)', 7), ('Specifications', 'Dust/Water Rating', 'IP66 (IEC 60529:2001)', 8), ('Specifications', 'Size with handle (w x d x h)', 'Control panel on both faces: 183 x 181 x 348 mm Control panel single face: 183 x 174 x 348 mm', 9)) as v(g, l, v, o) where sku = 'IM-100-SERIES';
insert into product_images (product_id, url, alt, sort_order) select id, '/catalog/products/1789726509978_product-gallery-im100v2_01.webp', 'iM-100 Series', 0 from products where sku = 'IM-100-SERIES';
insert into products (sku, slug, name, brand_id, manufacturer, category_id, model_number, short_description, description, unit, selling_price, tax_rate, price_visibility, reorder_threshold, is_featured, featured_rank, status, is_sample_data, features, warranty) values ('IM-50-SERIES', 'im-50-series', 'iM-50 Series', (select id from brands where slug = 'sokkia'), 'Sokkia', (select id from categories where slug = 'optical-instruments'), 'iM-50 Series', 'The iM-50 Series is the perfect entry-level site layout and survey tool offering reliability and flexibility without sacrificing cost or functionality. The sleek design is built tough, with a water and dustproof IP66 rating, integrated Bluetooth® capability and an internal antenna, enabling you to deliver measurements cable-free to your data controller, streamlining your equipment weight and workflow. The iM-50 is also armed with a top line EDM, generous internal memory storage, and SDRbasic on-board software so you have everything you need to get the job done out in the field.', 'The iM-50 Series is a the im-50 series is the perfect entry-level site layout and survey tool offering reliability and flexibility without sacrificing cost or functionality. the sleek design is built tough, with a water and dustproof ip66 rating, integrated bluetooth® capability and an internal antenna, enabling you to deliver measurements cable-free to your data controller, streamlining your equipment weight and workflow. the im-50 is also armed with a top line edm, generous internal memory storage, and sdrbasic on-board software so you have everything you need to get the job done out in the field. from Sokkia, part of our Optical Instruments range. Key specifications — USB Memory: Up to 32 GB; Internal Memory: 50,000 points; Reflectorless: Up to 500 m; Prism Range: Up to 4,000 m. Contact our team for pricing, availability, demonstrations and after-sales support.', 'Nos', null, 18, 'on_request', 1, false, 100, 'active', false, array['Integrated Construction and Survey Application Software','Fast, accurate, and powerful EDM','Reflectorless up to 500m','Prism range up to 4,000 m','Advanced angle accuracy (2" or 5")']::text[], 'As per manufacturer warranty terms.') on conflict (sku) do update set name = excluded.name, brand_id = excluded.brand_id, category_id = excluded.category_id, short_description = excluded.short_description, description = excluded.description, features = excluded.features, is_featured = excluded.is_featured, featured_rank = excluded.featured_rank, status = 'active';
insert into product_specifications (product_id, spec_group, label, value, sort_order) select id, v.g, v.l, v.v, v.o from products, (values ('Overview', 'Type', 'The iM-50 Series is the perfect entry-level site layout and survey tool offering reliability and flexibility without sacrificing cost or functionality. The sleek design is built tough, with a water and dustproof IP66 rating, integrated Bluetooth® capability and an internal antenna, enabling you to deliver measurements cable-free to your data controller, streamlining your equipment weight and workflow. The iM-50 is also armed with a top line EDM, generous internal memory storage, and SDRbasic on-board software so you have everything you need to get the job done out in the field.', 0), ('Specifications', 'USB Memory', 'Up to 32 GB', 1), ('Specifications', 'Internal Memory', '50,000 points', 2), ('Specifications', 'Reflectorless', 'Up to 500 m', 3), ('Specifications', 'Prism Range', 'Up to 4,000 m', 4), ('Specifications', 'Measuring Time', 'Fast measuring time - Fine: 0.9 s (Initial 1.7 s) Rapid: 0.7 s (Initial 1.4 s)', 5), ('Specifications', 'Tracking', '0.3 s (Initial 1.4 s)', 6), ('Specifications', 'Battery Life', 'Up to 14 hours of battery life in Eco mode.', 7)) as v(g, l, v, o) where sku = 'IM-50-SERIES';
