insert into products (sku, slug, name, brand_id, manufacturer, category_id, model_number, short_description, description, unit, selling_price, tax_rate, price_visibility, reorder_threshold, is_featured, featured_rank, status, is_sample_data, features, warranty) values ('IM-60-SERIES', 'im-60-series', 'iM-60 Series', (select id from brands where slug = 'sokkia'), 'Sokkia', (select id from categories where slug = 'optical-instruments'), 'iM-60 Series', 'The iM-60 Series is the ideal entry-level solution for site layout and surveying, delivering dependable performance, flexibility, and value. Designed to withstand tough field conditions, the iM-60 features a rugged IP66-rated water- and dust-resistant construction. For added convenience and productivity, models equipped with the optional integrated Bluetooth® and internal antenna provide seamless cable-free communication with your data controller. Combined with a powerful EDM, ample internal memory, and SDRbasic on-board software, the iM-60 gives professionals the essential tools needed to work efficiently and confidently in the field.', 'The iM-60 Series is a the im-60 series is the ideal entry-level solution for site layout and surveying, delivering dependable performance, flexibility, and value. designed to withstand tough field conditions, the im-60 features a rugged ip66-rated water- and dust-resistant construction. for added convenience and productivity, models equipped with the optional integrated bluetooth® and internal antenna provide seamless cable-free communication with your data controller. combined with a powerful edm, ample internal memory, and sdrbasic on-board software, the im-60 gives professionals the essential tools needed to work efficiently and confidently in the field. from Sokkia, part of our Optical Instruments range. Key specifications — USB Memory: Up to 64 GB; Internal Memory: 50,000 points; Reflectorless: Up to 500 m; Display / Keyboard: Monochrome / Alphanumeric. Contact our team for pricing, availability, demonstrations and after-sales support.', 'Nos', null, 18, 'on_request', 1, false, 100, 'active', false, array['Integrated Survey and Construction Application Software','Fast, accurate, and powerful EDM','Reflectorless up to 500m','Prism range up to 4,000 m','Advanced angle accuracy (2" or 5")']::text[], 'As per manufacturer warranty terms.') on conflict (sku) do update set name = excluded.name, brand_id = excluded.brand_id, category_id = excluded.category_id, short_description = excluded.short_description, description = excluded.description, features = excluded.features, is_featured = excluded.is_featured, featured_rank = excluded.featured_rank, status = 'active';
insert into product_specifications (product_id, spec_group, label, value, sort_order) select id, v.g, v.l, v.v, v.o from products, (values ('Overview', 'Type', 'The iM-60 Series is the ideal entry-level solution for site layout and surveying, delivering dependable performance, flexibility, and value. Designed to withstand tough field conditions, the iM-60 features a rugged IP66-rated water- and dust-resistant construction. For added convenience and productivity, models equipped with the optional integrated Bluetooth® and internal antenna provide seamless cable-free communication with your data controller. Combined with a powerful EDM, ample internal memory, and SDRbasic on-board software, the iM-60 gives professionals the essential tools needed to work efficiently and confidently in the field.', 0), ('Specifications', 'USB Memory', 'Up to 64 GB', 1), ('Specifications', 'Internal Memory', '50,000 points', 2), ('Specifications', 'Reflectorless', 'Up to 500 m', 3), ('Specifications', 'Display / Keyboard', 'Monochrome / Alphanumeric', 4), ('Specifications', 'Dust & waterproof rating', 'IP66', 5), ('Specifications', 'Battery Life', 'Up to 14 hours of battery life in Eco mode.', 6)) as v(g, l, v, o) where sku = 'IM-60-SERIES';
insert into product_images (product_id, url, alt, sort_order) select id, '/catalog/products/1789724843879_product-gallert-im-60-series01.webp', 'iM-60 Series', 0 from products where sku = 'IM-60-SERIES';
insert into products (sku, slug, name, brand_id, manufacturer, category_id, model_number, short_description, description, unit, selling_price, tax_rate, price_visibility, reorder_threshold, is_featured, featured_rank, status, is_sample_data, features, warranty) values ('IX-1500-700-ROBOTIC-TOTAL-STATION', 'ix-1500-700-robotic-total-station', 'iX-1500/700 Robotic Total Station', (select id from brands where slug = 'sokkia'), 'Sokkia', (select id from categories where slug = 'optical-instruments'), 'iX-1500/700 Robotic Total Station', 'Built for job site mobility, the flagship iX Series robotic total station enables accurate and productive workflows for highly demanding survey and construction applications. Precisely lay out or survey more points in less time and improve quality and consistency. Easy-to-use digital processes with repeatably accurate results mean less rework and better quality control. iX is one professional tool that does it all for survey and layout.', 'The iX-1500/700 Robotic Total Station is a built for job site mobility, the flagship ix series robotic total station enables accurate and productive workflows for highly demanding survey and construction applications. precisely lay out or survey more points in less time and improve quality and consistency. easy-to-use digital processes with repeatably accurate results mean less rework and better quality control. ix is one professional tool that does it all for survey and layout. from Sokkia, part of our Optical Instruments range. Key specifications — Motor: Brushless Direct Current (BLDC) motor; Tracking range: 360° Prism ATP1/ATP1S: 600m (1968ft); Dual-axis compensator (Tilt): ±6''; Field Software: Sokkia Field/3rd parties. Contact our team for pricing, availability, demonstrations and after-sales support.', 'Nos', null, 18, 'on_request', 1, false, 100, 'active', false, array['Precise positioning with single-person or two-person operation','High-speed Brushless Direct Current motors','Easy-to-use with Sokkia Field or 3rd-party software','Seamless integration into BIM workflows','Available in iX-1500 and iX-700 models with multiple accuracy levels','Three-year instrument and five-year motor warranty','Ultra-rugged IP65 dust and water resistance']::text[], 'As per manufacturer warranty terms.') on conflict (sku) do update set name = excluded.name, brand_id = excluded.brand_id, category_id = excluded.category_id, short_description = excluded.short_description, description = excluded.description, features = excluded.features, is_featured = excluded.is_featured, featured_rank = excluded.featured_rank, status = 'active';
insert into product_specifications (product_id, spec_group, label, value, sort_order) select id, v.g, v.l, v.v, v.o from products, (values ('Overview', 'Type', 'Built for job site mobility, the flagship iX Series robotic total station enables accurate and productive workflows for highly demanding survey and construction applications. Precisely lay out or survey more points in less time and improve quality and consistency. Easy-to-use digital processes with repeatably accurate results mean less rework and better quality control. iX is one professional tool that does it all for survey and layout.', 0), ('Specifications', 'Motor', 'Brushless Direct Current (BLDC) motor', 1), ('Specifications', 'Tracking range', '360° Prism ATP1/ATP1S: 600m (1968ft)', 2), ('Specifications', 'Dual-axis compensator (Tilt)', '±6''', 3), ('Specifications', 'Field Software', 'Sokkia Field/3rd parties', 4), ('Specifications', 'Data Storage', 'Internal: 1GB USB: Up to 32GB', 5), ('Specifications', 'Interface', 'RS-232C, USB 2.0 (Type A and mini B)', 6), ('Specifications', 'LongLink™', 'Yes. Up to 600m', 7), ('Specifications', 'WiFi', 'IEEE 802.11 b/g/n', 8)) as v(g, l, v, o) where sku = 'IX-1500-700-ROBOTIC-TOTAL-STATION';
