rray['0.5” / 1” Angular Accuracy','Exclusive Reflector Prescan technology','0.5 mm Ultra High-precision Distance Measurement','Auto-Pointing Accuracy of 1','Laser Option for Tunneling','IP65 Enhanced Durability for Long-term Installations']::text[], 'As per manufacturer warranty terms.') on conflict (sku) do update set name = excluded.name, brand_id = excluded.brand_id, category_id = excluded.category_id, short_description = excluded.short_description, description = excluded.description, features = excluded.features, is_featured = excluded.is_featured, featured_rank = excluded.featured_rank, status = 'active';
