Our range covers small walk-behind rollers for patchwork and footpaths, ride-on road rollers for larger areas, forward and reversible plate compactors for granular soils, and tamping rammers for trenches and cohesive soils — backed by service and genuine spares.', array['Walk-behind and ride-on road rollers','Single and double drum rollers','Forward and reversible plate compactors','Tamping rammers for trenches and clay','Scarifiers for surface preparation','Service, spares and operator guidance']::text[], array['Road and highway works','Paver and footpath bedding','Trench and pipeline backfill','Building foundations','Parking areas and driveways','Industrial yards']::text[], '[{"title": "Roller or plate?", "text": "Rollers suit larger open areas and asphalt; plate compactors suit confined areas, pavers and patchwork."}, {"title": "Soil type", "text": "Granular soils compact best with vibration (plates, rollers); clay and silt need the impact of a tamping rammer."}, {"title": "Layer depth", "text": "Deeper lifts need higher centrifugal force \u2014 choose reversible plates or heavier rollers for thick layers."}, {"title": "Site access", "text": "Walk-behind machines fit narrow sites and trenches; ride-on rollers give higher output on open ground."}]'::jsonb, '[{"q": "Which machine is best for trenches?", "a": "Tamping rammers and narrow plate compactors work best in trenches and around pipes."}, {"q": "Do you provide service and spares?", "a": "Yes \u2014 commissioning, maintenance, breakdown support and genuine spares through our service network."}, {"q": "How do I get a quotation?", "a": "Use Get Enquiry, add products to your cart, or message us on WhatsApp with your site requirement."}]'::jsonb) on conflict (slug) do update set name = excluded.name, description = excluded.description, image_url = excluded.image_url, sort_order = excluded.sort_order, is_active = true, overview = excluded.overview, key_points = excluded.key_points, applications = excluded.applications, buying_guide = excluded.buying_guide, faqs = excluded.faqs;

